        angle = M_PI / 2.0;// Top -> Right -> Bottom -> Left -> Top
    if (spindirection == RotationDirection::CCW)
        angle = -M_PI / 2.0;// Top -> Left -> Bottom -> Right -> Top

    spin(angle);
}

