DimensionGeometry TechDraw::isValidHybrid(ReferenceVector refs)
{
    if (refs.empty()) {
        return DimensionGeometry::isInvalid;
    }

    int vertexCount(0);
    int edgeCount(0);
    for (auto& ref : refs) {
        if (DU::getGeomTypeFromName(ref.getSubName()) == "Vertex") {
            vertexCount++;
        }
        if (DU::getGeomTypeFromName(ref.getSubName()) == "Edge") {
            edgeCount++;
