Point Mid(const Span& span)
{
    // mid point of a span
    if (span.dir) {
        CLine chord(span.p0, span.p1);
        if (chord.ok) {
            CLine bisector(Mid(span.p0, span.p1), ~chord.v, false);
            return Intof((span.dir == CW) ? FARINT : NEARINT, bisector, Circle(span));
        }
        else {
