    MeasureType mode;

    int verts = 0;
    int edges = 0;
    int lines = 0;
    int circles = 0;
    int faces = 0;
    int planes = 0;
    int cylinders = 0;
    int cones = 0;
    int torus = 0;
    int spheres = 0;
    int vols = 0;
    int other = 0;

    for (; obj != objects.end(); ++obj, ++subEl) {
        TopoDS_Shape refSubShape;
        try {
            refSubShape =
                Part::Feature::getShape(*obj,
                                        (*subEl).c_str(),
                                        nullptr,
                                        nullptr,
                                        Part::Feature::NeedSubElement | Part::Feature::ResolveLink
                                            | Part::Feature::Transform);

            if (refSubShape.IsNull()) {
                return MeasureType::Invalid;
            }
        }
        catch (Standard_Failure& e) {
            std::stringstream errorMsg;

            errorMsg << "Measurement - getType - " << e.GetMessageString() << std::endl;
            throw Base::CADKernelError(e.GetMessageString());
        }

        switch (refSubShape.ShapeType()) {
            case TopAbs_VERTEX: {
                verts++;
            } break;
            case TopAbs_EDGE: {
                edges++;
                TopoDS_Edge edge = TopoDS::Edge(refSubShape);
                BRepAdaptor_Curve sf(edge);

                if (sf.GetType() == GeomAbs_Line) {
                    lines++;
                }
                else if (sf.GetType() == GeomAbs_Circle) {
                    circles++;
                }
            } break;
            case TopAbs_FACE: {
                faces++;
                TopoDS_Face face = TopoDS::Face(refSubShape);
                BRepAdaptor_Surface sf(face);

                if (sf.GetType() == GeomAbs_Plane) {
                    planes++;
                }
                else if (sf.GetType() == GeomAbs_Cylinder) {
                    cylinders++;
                }
                else if (sf.GetType() == GeomAbs_Sphere) {
                    spheres++;
                }
                else if (sf.GetType() == GeomAbs_Cone) {
                    cones++;
                }
                else if (sf.GetType() == GeomAbs_Torus) {
                    torus++;
                }
            } break;
            case TopAbs_SOLID: {
                vols++;
            } break;
            default:
                other++;
                break;
        }
    }

    if (other > 0) {
        mode = MeasureType::Invalid;
    }
    else if (vols > 0) {
