    else {
        std::vector<TopoShape> shapes;
        for (auto& sub : subs) {
            shapes.push_back(Part::Feature::getTopoShape(profile,
                                                         sub.c_str(),
                                                         nullptr,
                                                         nullptr,
                                                         subShapeOptions));
        }
        shape = TopoShape(shape.Tag).makeElementCompound(shapes);
    }
    if (shape.isNull()) {
        throw Part::NullShapeException("Linked shape object is empty");
    }
    return shape;
}


