        std::vector<TopoShape> shapes;
        for (auto& obj : Sections.getValues()) {
            shapes.emplace_back(getTopoShape(obj));
            if (shapes.back().isNull()) {
                return new App::DocumentObjectExecReturn("Invalid section link");
