short FeatureBlendCurve::mustExecute() const
{
    if (StartEdge.isTouched()) {
        return 1;
    }
    if (StartParameter.isTouched()) {
        return 1;
    }
    if (StartContinuity.isTouched()) {
        return 1;
    }
