    Py::Object show(const Py::Tuple& args)
    {
        PyObject *pcObj = nullptr;
        const char *name = "Shape";
        if (!PyArg_ParseTuple(args.ptr(), "O!|s", &(TopoShapePy::Type), &pcObj, &name))
            throw Py::Exception();

