        }
        Part::Feature *pcFeature = pcDoc->addObject<Part::Feature>(name);
        // copy the data
        pcFeature->Shape.setValue(shape);
        pcFeature->purgeTouched();
        return Py::asObject(pcFeature->getPyObject());
