TopoShape Feature::simplifyCompound(TopoShape compoundShape)
{
    std::array<TopAbs_ShapeEnum, 7> simplificationPriority = {  
                                            TopAbs_SOLID,
                                            TopAbs_COMPSOLID,
                                            TopAbs_FACE,
                                            TopAbs_SHELL,
                                            TopAbs_SHELL,
                                            TopAbs_WIRE,
