                    if (face.isNull()) {
                        throw Base::ValueError("SketchBased: Failed to extract face");
                    }
                    faceList.push_back(face);
                    ret ++;
                }
            }
        }
    }
    if (ret == 0){
        return 0;
    }
    if (ret == 1){
        upToShape = faceList[0];
        return 1;
    }

