std::string Data::newElementName(const char* name)
{
    if (!name) {
        return {};
    }
    const char* dot = strrchr(name, '.');
    if (!dot || dot == name) {
        return name;
    }
    const char* c = dot - 1;
    for (; c != name; --c) {
        if (*c == '.') {
            ++c;
            break;
        }
    }
    if (isMappedElement(c)) {
        return std::string(name, dot - name);
    }
    return name;
}
