bool ConsoleHistory::prev( const QString &prefix )
{
    bool wentPrev = false;

    // store prefix if it's the first history access
    if (_it == _history.cend()) {
        _prefix = prefix;
    }

    // while we didn't go back or reach history's begin ...
    while (!wentPrev && _it != _history.cbegin()) {
