void Matrix::GetRotation(double& ax, double& ay, double& az) const
{
    // return the rotations
    if (m_unit) {
        ax = ay = az = 0;
        return;
    }
    double a;  /* cos(bx) */
    double b;  /* sin(bx) */
    double c;  /* cos(by) */
    double d;  /* sin(by) */
    double ee; /* cos(bz) */
    double f;  /* sin(bz) */
    double sx, sy, sz;
    GetScale(sx, sy, sz);
    if (this->m_mirrored == -1) {
        FAILURE(L"Don't know mirror - use IsMirrored method on object");
    }
    if (this->m_mirrored) {
        sx = -sx;
    }

    // solve for d and decide case and solve for a, b, c, e and f
    d = -e[8] / sz;
    if ((c = (1 - d) * (1 + d)) > 0.001) {
        // case 1
        c = sqrt(c);
        a = e[10] / sz / c;
        b = e[9] / sz / c;
        ee = e[0] / sx / c;
        f = e[4] / sy / c;
    }
    else {
        // case 2
        double coef;
        double p, q;

        d = (d < 0) ? -1 : 1;
        c = 0;
        p = d * e[5] / sy - e[2] / sx;
        q = d * e[6] / sy + e[1] / sx;
        if ((coef = sqrt(p * p + q * q)) > 0.001) {
            a = q / coef;
            b = p / coef;
            ee = b;
            f = -d * b;
        }
        else {
            /* dependent pairs */
            a = e[5] / sy;
            b = -e[6] / sy;
            ee = 1;
            f = 0;
        }
    }

    // solve and return ax, ay and az
    ax = atan2(b, a);
    ay = atan2(d, c);
    az = atan2(f, ee);
}
