void Matrix_gauss(Matrix a, Matrix b)
{
    int ipiv[4], indxr[4], indxc[4];
    int i {}, j {}, k {}, l {}, ll {};
    int irow = 0, icol = 0;
    double big {}, pivinv {};
    double dum {};
    for (j = 0; j < 4; j++) {
        ipiv[j] = 0;
    }
    for (i = 0; i < 4; i++) {
        big = 0;
        for (j = 0; j < 4; j++) {
            if (ipiv[j] != 1) {
                for (k = 0; k < 4; k++) {
                    if (ipiv[k] == 0) {
                        if (fabs(a[4 * j + k]) >= big) {
                            big = fabs(a[4 * j + k]);
                            irow = j;
                            icol = k;
                        }
                    }
                    else if (ipiv[k] > 1) {
                        return; /* Singular matrix */
                    }
                }
            }
        }
        ipiv[icol] = ipiv[icol] + 1;
        if (irow != icol) {
            for (l = 0; l < 4; l++) {
                dum = a[4 * irow + l];
                a[4 * irow + l] = a[4 * icol + l];
                a[4 * icol + l] = dum;
            }
            for (l = 0; l < 4; l++) {
                dum = b[4 * irow + l];
                b[4 * irow + l] = b[4 * icol + l];
                b[4 * icol + l] = dum;
            }
        }
        indxr[i] = irow;
        indxc[i] = icol;
        if (a[4 * icol + icol] == 0.0) {
            return;
        }
        pivinv = 1.0 / a[4 * icol + icol];
        a[4 * icol + icol] = 1.0;
        for (l = 0; l < 4; l++) {
            a[4 * icol + l] = a[4 * icol + l] * pivinv;
        }
        for (l = 0; l < 4; l++) {
            b[4 * icol + l] = b[4 * icol + l] * pivinv;
        }
        for (ll = 0; ll < 4; ll++) {
            if (ll != icol) {
                dum = a[4 * ll + icol];
                a[4 * ll + icol] = 0;
                for (l = 0; l < 4; l++) {
                    a[4 * ll + l] = a[4 * ll + l] - a[4 * icol + l] * dum;
                }
                for (l = 0; l < 4; l++) {
                    b[4 * ll + l] = b[4 * ll + l] - b[4 * icol + l] * dum;
                }
            }
        }
    }
    for (l = 3; l >= 0; l--) {
        if (indxr[l] != indxc[l]) {
            for (k = 0; k < 4; k++) {
                dum = a[4 * k + indxr[l]];
                a[4 * k + indxr[l]] = a[4 * k + indxc[l]];
                a[4 * k + indxc[l]] = dum;
            }
        }
    }
}
